tape( 'the function supports view offsets (full=true)', function test( t ) {
	var expected;
	var out0;
	var out1;

	out0 = new Float64Array( 5 );
	out1 = new Float64Array( out0.buffer, out0.BYTES_PER_ELEMENT*1 );

	ghelmert( 'row-major', true, 2, out1, 2 );

	expected = new Float64Array([
		1.0 / sqrt( 2 ),
		1.0 / sqrt( 2 ),
		1.0 / sqrt( 2 ),
		-1.0 / sqrt( 2 )
	]);

	t.deepEqual( out1, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports view offsets (full=false)', function test( t ) {
	var expected;
	var out0;
	var out1;

	out0 = new Float64Array( 7 );
	out1 = new Float64Array( out0.buffer, out0.BYTES_PER_ELEMENT*1 );

	ghelmert( 'row-major', false, 3, out1, 3 );

	expected = new Float64Array([
		1.0 / sqrt( 2 ),
		-1.0 / sqrt( 2 ),
		0.0,
		1.0 / sqrt( 6 ),
		1.0 / sqrt( 6 ),
		-2.0 / sqrt( 6 )
	]);

	t.deepEqual( out1, expected, 'returns expected value' );
	t.end();
});
